void NotificationsInstanceAsyncWaiter::Init(
    ::mojo::PendingRemote<NotificationsHost> host_remote) {
  base::RunLoop loop;
  proxy_->Init(std::move(host_remote),
      base::BindOnce(
          [](base::RunLoop* loop) {
            loop->Quit();
          },
          &loop));
  loop.Run();
}








